  where c.oid is null or pg_catalog.pg_get_userbyid(c.relowner) is distinct from expected.owner
   or exists (
     select 1 from (
       select a.grantee, a.grantor, a.privilege_type, a.is_grantable
       from aclexplode(coalesce(c.relacl, acldefault('r', c.relowner))) a
       except
       select e.grantee, e.grantor, e.privilege_type, e.is_grantable
       from aclexplode(expected.acl::aclitem[]) e
     ) tb_extra
   )
   or exists (
