begin
  if auth.role() is distinct from 'service_role' then
    return jsonb_build_object('ok', false, 'code', 'FORBIDDEN');
  end if;
  return jsonb_build_object('ok', false, 'code', 'PAYMOB_EXTERNAL_DEFERRED');
